+/** Chooses a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  const raw = Array.isArray(header) ? header.join(",") : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  const candidates = [];
+  raw.split(",").forEach((part, index) => {
+    const [rawTag, ...params] = part.split(";");
+    const tag = rawTag.trim().toLowerCase();
+    if (!/^[a-z]+(?:-[a-z0-9]+)*$/.test(tag)) return;
+    const lang = tag.split("-")[0];
+    if (!LANGUAGES.includes(lang)) return;
+    let q = 1;
+    for (const param of params) {
+      const eq = param.indexOf("=");
+      if (eq === -1) continue;
+      if (param.slice(0, eq).trim().toLowerCase() !== "q") continue;
+      const val = param.slice(eq + 1).trim();
+      if (!/^(?:0(?:\.\d+)?|1(?:\.0+)?|\.\d+)$/.test(val)) return;
+      q = Number(val);
+    }
+    if (q > 0) candidates.push({ lang, q, index });
+  });
+  if (!candidates.length) return fallback;
+  candidates.sort((a, b) => b.q - a.q || a.index - b.index);
+  return candidates[0].lang;
+}
